import{_ as i,o as l,c as e,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Optimizing Ceph IO for High Throughput Particle Physics Workflows","description":"","frontmatter":{"title":"Optimizing Ceph IO for High Throughput Particle Physics Workflows","date":"2023-05-05T00:00:00.000Z","updated":"2023-05-05T00:00:00.000Z","tags":["[Ceph]","[High Throughput]","[Particle Physics]","[IO Optimization]","[Storage Cluster]"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/Optimizing_Ceph_IO_for_High_Throughput_Particle_Physics_Workflows.md","filePath":"posts/2023/Optimizing_Ceph_IO_for_High_Throughput_Particle_Physics_Workflows.md","lastUpdated":1780459816000}'),o={name:"posts/2023/Optimizing_Ceph_IO_for_High_Throughput_Particle_Physics_Workflows.md"};function t(h,a,s,n,p,u){return l(),e("div",null,[...a[0]||(a[0]=[r('<p>会议纪要</p><h3 id="会议主题-ceph存储系统在大型科学实验中的应用与优化" tabindex="-1">会议主题：Ceph存储系统在大型科学实验中的应用与优化 <a class="header-anchor" href="#会议主题-ceph存储系统在大型科学实验中的应用与优化" aria-label="Permalink to &quot;会议主题：Ceph存储系统在大型科学实验中的应用与优化&quot;">​</a></h3><h4 id="会议时间-具体日期" tabindex="-1">会议时间：[具体日期] <a class="header-anchor" href="#会议时间-具体日期" aria-label="Permalink to &quot;会议时间：[具体日期]&quot;">​</a></h4><h4 id="会议地点-具体地点" tabindex="-1">会议地点：[具体地点] <a class="header-anchor" href="#会议地点-具体地点" aria-label="Permalink to &quot;会议地点：[具体地点]&quot;">​</a></h4><h4 id="主讲人-tom" tabindex="-1">主讲人：Tom <a class="header-anchor" href="#主讲人-tom" aria-label="Permalink to &quot;主讲人：Tom&quot;">​</a></h4><h4 id="参会人员-参会人员名单" tabindex="-1">参会人员：[参会人员名单] <a class="header-anchor" href="#参会人员-参会人员名单" aria-label="Permalink to &quot;参会人员：[参会人员名单]&quot;">​</a></h4><h4 id="会议内容总结" tabindex="-1">会议内容总结： <a class="header-anchor" href="#会议内容总结" aria-label="Permalink to &quot;会议内容总结：&quot;">​</a></h4><ol><li><p><strong>主讲人介绍</strong>：</p><ul><li>Tom来自英国的科学与技术设施委员会（STFC），负责设计和构建存储解决方案，支持设施用户和外部用户。</li></ul></li><li><p><strong>STFC背景</strong>：</p><ul><li>STFC运营大型科学资源，支持大量数据密集型科学研究，并参与UK Research and Innovation组织。</li></ul></li><li><p><strong>Ceph集群Echo介绍</strong>：</p><ul><li>Echo是STFC运行的最大的Ceph集群，已投入生产超过五年，从10PB增长到64.65PB，主要用于LHC实验的磁盘存储。</li><li>Echo使用XrootD作为数据传输框架，通过xrdCEPH和librados striper与Ceph集群交互。</li></ul></li><li><p><strong>Ceph集群Echo的优化</strong>：</p><ul><li>发现小读取性能问题，并通过缓存和其他优化措施进行缓解。</li><li>通过优化xrdCEPH和librados striper，特别是移除锁定行为，显著提高了性能。</li></ul></li><li><p><strong>后续行动计划</strong>：</p><ul><li>继续探索和利用librados的其他高级功能，如异步操作和原子操作，以进一步优化性能。</li><li>考虑在OSD级别实施校验和计算，以提高外部网关的效率。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h4><ul><li>确认了Ceph集群Echo的性能优化措施，并计划进一步探索librados的高级功能。</li><li>决定继续监控和优化LHC实验的数据处理流程，以应对未来高亮度LHC的挑战。</li></ul><h4 id="后续行动" tabindex="-1">后续行动： <a class="header-anchor" href="#后续行动" aria-label="Permalink to &quot;后续行动：&quot;">​</a></h4><ul><li>实施xrdCEPH和librados striper的优化版本，并监控其性能。</li><li>探索在OSD级别实施校验和计算的可能性。</li><li>继续参与LHC实验的数据挑战，确保基础设施的准备就绪。</li></ul><h4 id="感谢人员" tabindex="-1">感谢人员： <a class="header-anchor" href="#感谢人员" aria-label="Permalink to &quot;感谢人员：&quot;">​</a></h4><ul><li>感谢Joe Fish, Alexander, James等人在开发和实施优化措施中的关键贡献。</li></ul><h4 id="会议结束" tabindex="-1">会议结束： <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束：&quot;">​</a></h4><ul><li>会议在感谢和掌声中结束，准备进入下一个议程。</li></ul>',16)])])}const _=i(o,[["render",t]]);export{c as __pageData,_ as default};
